    "_%n engagement in {month}_::_%n engagement in {month}_" : ["%n interakcija v mesecu {month}","%n interakciji v mesecu {month}","%n interakcije v mesecu {month}","%n interakcij v mesecu {month}"],
    "_%n follower in {month}_::_%n followers in {month}_" : ["%n sledilec v mesecu {month}","%n sledilca v mesecu {month}","%n sledilci v mesecu {month}","%n sledilcev v mesecu {month}"],
    "_%n post in {month}_::_%n posts in {month}_" : ["%n objava v mesecu {month}","%n objavi v mesecu {month}","%n objave v mesecu {month}","%n objav v mesecu {month}"],
